$('esp-windows').onclick=()=>$('esp-layout-dialog').showModal();$('esp-close-layout').onclick=()=>$('esp-layout-dialog').close();
for(const id of ESP_PANELS)$('esp-panel-toggle-'+id).onchange=()=>{layout[id]=$('esp-panel-toggle-'+id).checked;applyLayout();};
for(const[id,panels]of Object.entries(ESP_LAYOUT_PRESETS))$('esp-preset-'+id).onclick=()=>{layout=Object.fromEntries(ESP_PANELS.map(p=>[p,panels.includes(p)]));applyLayout();$('esp-layout-dialog').close();};applyLayout();
document.addEventListener('visibilitychange',()=>{if(document.hidden){clearTimeout(saveTimer);save();}});window.addEventListener('pagehide',()=>{clearTimeout(saveTimer);save();});

navigator.serviceWorker?.addEventListener('message',({data})=>{if(data?.type==='shell-ready'&&data.cache===APP_CACHE)$('esp-cache-status').textContent='Uygulama önbelleği hazır';});

function currentKey(){try{return espSourceKey(chip,source,files);}catch{return null;}}
function activeContent(){return activeFile==='sketch.ino'?source:files.find(f=>f.name===activeFile)?.content||'';}
function renderFiles(){if(!files.some(f=>f.name===activeFile)&&activeFile!=='sketch.ino')activeFile='sketch.ino';const select=$('esp-source-file');select.replaceChildren();for(const name of ['sketch.ino',...files.map(f=>f.name)]){const option=document.createElement('option');option.value=name;option.textContent=name;select.append(option);}select.value=activeFile;$('esp-file-edit').disabled=activeFile==='sketch.ino';}
function invalidateFiles(){workspaceRevision++;dirty=true;example='custom';cancelCompile();stopRuntime();editor.setDiagnostics([]);$('esp-firmware-status').textContent='Kaynak dosyaları değişti · yeniden derleyin';renderFiles();renderExamples();save();}
$('esp-source-file').onchange=()=>{activeFile=$('esp-source-file').value;renderFiles();editor.setValue(activeContent());editor.setDiagnostics([]);};
let fileMode='add';
$('esp-file-add').onclick=()=>{fileMode='add';$('esp-file-error').textContent='';$('esp-file-name').value='module.cpp';$('esp-file-delete').hidden=true;$('esp-file-dialog').showModal();};
$('esp-file-edit').onclick=()=>{fileMode='rename';$('esp-file-error').textContent='';$('esp-file-name').value=activeFile;$('esp-file-delete').hidden=false;$('esp-file-dialog').showModal();};
$('esp-close-file').onclick=()=>$('esp-file-dialog').close();
$('esp-file-form').onsubmit=e=>{e.preventDefault();try{const name=$('esp-file-name').value.trim(),next=structuredClone(files);if(fileMode==='add')next.push({name,content:name.endsWith('.cpp')?'#include "Arduino.h"\n':'#pragma once\n'});else next.find(f=>f.name===activeFile).name=name;normalizeESPFiles(source,next);checkpoint();files=next;activeFile=name;editor.setValue(activeContent());invalidateFiles();$('esp-file-dialog').close();status('Dosya kaydedildi · include yollarını kontrol edin');}catch(error){$('esp-file-error').textContent=error.message;status(error.message,true);}};
$('esp-file-delete').onclick=()=>{if(activeFile==='sketch.ino')return;checkpoint();files=files.filter(f=>f.name!==activeFile);activeFile='sketch.ino';editor.setValue(source);invalidateFiles();$('esp-file-dialog').close();status('Dosya silindi · kaynak geçmişinde kayıtlı');};renderFiles();

function showCompilerDiagnostics(log){const items=parseCompilerDiagnostics(log,['sketch.ino',...files.map(f=>f.name)]),first=items.find(d=>d.navigable&&d.severity==='error');if(first&&first.file!==activeFile){activeFile=first.file;renderFiles();editor.setValue(activeContent());}editor.setDiagnostics(items.filter(d=>d.file===activeFile||!d.navigable),'Clang');if(first)editor.goToLine(first.line);}
